python3 -c "
import pathlib
p = pathlib.Path('src/types/checker/type_compat/unions.rs')
t = p.read_text()
old = '''                _ => PhpType::Resource(None),
            });
        }
        None
    }'''
new = '''                _ => PhpType::Resource(None),
            });
        }
        // EXPERIMENT: widen a scalar reassignment to Mixed instead of refusing it.
        if matches!(
            existing,
            PhpType::Int | PhpType::Float | PhpType::Bool | PhpType::False | PhpType::Str
        ) && matches!(
            new_ty,
            PhpType::Int | PhpType::Float | PhpType::Bool | PhpType::False | PhpType::Str
        ) {
            return Some(PhpType::Mixed);
        }
        None
    }'''
assert t.count(old) == 1
p.write_text(t.replace(old, new, 1))
print('experiment applied')
